INSERT INTO cve (cve_id, description, severity, cvss_score, cvss_version, vuln_status, published_at, last_modified_at) VALUES
  ('CVE-2021-43803', 'Next.js is a React framework. In versions of Next.js prior to 12.0.5 or 11.1.3, invalid or malformed URLs could lead to a server crash. In order to be affected by this issue, the deployment must use Next.js versions above 11.1.0 and below 12.0.5, Node.js above 15.0.0, and next start or a custom server. Deployments on Vercel are not affected, along with similar environments where invalid requests are filtered before reaching Next.js. Versions 12.0.5 and 11.1.3 contain patches for this issue.', 'HIGH', 7.5, '3.1', 'Modified', '2021-12-10T00:15:11.827Z', '2026-06-17T04:11:28.210Z'),
  ('CVE-2021-44228', 'Apache Log4j2 2.0-beta9 through 2.15.0 (excluding security releases 2.12.2, 2.12.3, and 2.3.1) JNDI features used in configuration, log messages, and parameters do not protect against attacker controlled LDAP and other JNDI related endpoints. An attacker who can control log messages or log message parameters can execute arbitrary code loaded from LDAP servers when message lookup substitution is enabled. From log4j 2.15.0, this behavior has been disabled by default. From version 2.16.0 (along with 2.12.2, 2.12.3, and 2.3.1), this functionality has been completely removed. Note that this vulnerability is specific to log4j-core and does not affect log4net, log4cxx, or other Apache Logging Services projects.', 'CRITICAL', 10, '3.1', 'Analyzed', '2021-12-10T10:15:09.143Z', '2026-08-11T19:33:44.513Z'),
  ('CVE-2021-4081', 'pimcore is vulnerable to Improper Neutralization of Input During Web Page Generation (''Cross-site Scripting'')', 'MEDIUM', 6.1, '3.1', 'Modified', '2021-12-10T11:15:07.620Z', '2026-06-17T04:19:00.417Z'),
  ('CVE-2021-4082', 'pimcore is vulnerable to Cross-Site Request Forgery (CSRF)', 'MEDIUM', 4.3, '3.1', 'Modified', '2021-12-10T11:15:07.693Z', '2026-06-17T04:19:00.520Z'),
  ('CVE-2021-4084', 'pimcore is vulnerable to Improper Neutralization of Input During Web Page Generation (''Cross-site Scripting'')', 'MEDIUM', 6.1, '3.1', 'Modified', '2021-12-10T12:15:07.817Z', '2026-06-17T04:19:00.767Z'),
  ('CVE-2021-35978', 'An issue was discovered in Digi TransPort DR64, SR44 VC74, and WR. The ZING protocol allows arbitrary remote command execution with SUPER privileges. This allows an attacker (with knowledge of the protocol) to execute arbitrary code on the controller including overwriting firmware, adding/removing users, disabling the internal firewall, etc.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T13:15:07.620Z', '2026-06-17T03:58:08.427Z'),
  ('CVE-2021-37187', 'An issue was discovered on Digi TransPort devices through 2021-07-21. An authenticated attacker may read a password file (with reversible passwords) from the device, which allows decoding of other users'' passwords.', 'MEDIUM', 6.5, '3.1', 'Modified', '2021-12-10T13:15:07.667Z', '2026-06-17T04:00:13.260Z'),
  ('CVE-2021-37188', 'An issue was discovered on Digi TransPort devices through 2021-07-21. An authenticated attacker may load customized firmware (because the bootloader does not verify that it is authentic), changing the behavior of the gateway.', 'HIGH', 8.8, '3.1', 'Modified', '2021-12-10T13:15:07.710Z', '2026-06-17T04:00:13.390Z'),
  ('CVE-2021-37189', 'An issue was discovered on Digi TransPort Gateway devices through 5.2.13.4. They do not set the Secure attribute for sensitive cookies in HTTPS sessions, which could cause the user agent to send those cookies in cleartext over an HTTP session.', 'HIGH', 7.5, '3.1', 'Modified', '2021-12-10T13:15:07.753Z', '2026-06-17T04:00:13.520Z'),
  ('CVE-2021-40834', 'A user interface overlay vulnerability was discovered in F-secure SAFE Browser for Android. When user click on a specially crafted seemingly legitimate URL SAFE browser goes into full screen and hides the user interface. A remote attacker can leverage this to perform spoofing attack.', 'MEDIUM', 4.3, '3.1', 'Modified', '2021-12-10T14:15:10.093Z', '2026-06-17T04:07:30.460Z'),
  ('CVE-2021-3829', 'openwhyd is vulnerable to URL Redirection to Untrusted Site', 'MEDIUM', 6.1, '3.1', 'Modified', '2021-12-10T16:15:09.310Z', '2026-06-17T04:05:51.133Z'),
  ('CVE-2021-29214', 'A security vulnerability has been identified in HPE StoreServ Management Console (SSMC). An authenticated SSMC administrator could exploit the vulnerability to inject code and elevate their privilege in SSMC. The scope of this vulnerability is limited to SSMC. Note: The arrays being managed are not impacted by this vulnerability. This vulnerability impacts SSMC versions 3.4 GA to 3.8.1.', 'HIGH', 7.2, '3.1', 'Modified', '2021-12-10T17:15:07.480Z', '2026-06-17T03:47:24.750Z'),
  ('CVE-2021-36911', 'Stored Cross-Site Scripting (XSS) vulnerability discovered in WordPress Comment Engine Pro plugin (versions <= 1.0), could be exploited by users with Editor or higher role.', 'MEDIUM', 5.4, '3.1', 'Modified', '2021-12-10T17:15:07.537Z', '2026-06-17T03:59:37.017Z'),
  ('CVE-2021-37934', 'Due to insufficient server-side login-attempt limit enforcement, a vulnerability in /account/login in Huntflow Enterprise before 3.10.14 could allow an unauthenticated, remote user to perform multiple login attempts for brute-force password guessing.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T17:15:07.593Z', '2026-06-17T04:01:16.717Z'),
  ('CVE-2021-37935', 'An information disclosure vulnerability in the login page of Huntflow Enterprise before 3.10.4 could allow an unauthenticated, remote user to get information about the domain name of the configured LDAP server. An attacker could exploit this vulnerability by requesting the login page and searching for the "isLdap" JavaScript parameter in the HTML source code.', 'HIGH', 7.5, '3.1', 'Modified', '2021-12-10T17:15:07.637Z', '2026-06-17T04:01:16.833Z'),
  ('CVE-2021-31745', 'Session Fixation vulnerability in login.php in Pluck-CMS Pluck 4.7.15 allows an attacker to sustain unauthorized access to the platform. Because Pluck does not invalidate prior sessions after a password change, access can be sustained even after an administrator performs regular remediation attempts such as resetting their password.', 'HIGH', 7.5, '3.1', 'Modified', '2021-12-10T18:15:07.463Z', '2026-06-17T03:52:11.813Z'),
  ('CVE-2021-31746', 'Zip Slip vulnerability in Pluck-CMS Pluck 4.7.15 allows an attacker to upload specially crafted zip files, resulting in directory traversal and potentially arbitrary code execution.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T18:15:07.653Z', '2026-06-17T03:52:11.930Z'),
  ('CVE-2021-38917', 'IBM PowerVM Hypervisor FW860, FW940, and FW950 could allow an attacker that gains service access to the FSP can read and write arbitrary host system memory through a series of carefully crafted service procedures. IBM X-Force ID: 210018.', 'CRITICAL', 9.1, '3.1', 'Modified', '2021-12-10T18:15:07.847Z', '2026-06-17T04:02:49.663Z'),
  ('CVE-2021-38937', 'IBM PowerVM Hypervisor FW940, FW950, and FW1010 could allow an authenticated user to cause the system to crash using a specially crafted IBMi Hypervisor call. IBM X-Force ID: 210894.', 'MEDIUM', 6.5, '3.1', 'Modified', '2021-12-10T18:15:08.083Z', '2026-06-17T04:02:51.707Z'),
  ('CVE-2021-43813', 'Grafana is an open-source platform for monitoring and observability. Grafana prior to versions 8.3.2 and 7.5.12 contains a directory traversal vulnerability for fully lowercase or fully uppercase .md files. The vulnerability is limited in scope, and only allows access to files with the extension .md to authenticated users only. Grafana Cloud instances have not been affected by the vulnerability. Users should upgrade to patched versions 8.3.2 or 7.5.12. For users who cannot upgrade, running a reverse proxy in front of Grafana that normalizes the PATH of the request will mitigate the vulnerability. The proxy will have to also be able to handle url encoded paths. Alternatively, for fully lowercase or fully uppercase .md files, users can block /api/plugins/.*/markdown/.* without losing any functionality beyond inlined plugin help text.', 'MEDIUM', 4.3, '3.1', 'Modified', '2021-12-10T18:15:08.260Z', '2026-06-17T04:11:29.440Z'),
  ('CVE-2021-27983', 'Remote Code Execution (RCE) vulnerability exists in MaxSite CMS v107.5 via the Documents page.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T19:15:07.740Z', '2026-06-17T03:45:41.503Z'),
  ('CVE-2021-27984', 'In Pluck-4.7.15 admin background a remote command execution vulnerability exists when uploading files.', 'HIGH', 8.1, '3.1', 'Modified', '2021-12-10T19:15:07.783Z', '2026-06-17T03:45:41.617Z'),
  ('CVE-2021-31747', 'Missing SSL Certificate Validation issue exists in Pluck 4.7.15 in update_applet.php, which could lead to man-in-the-middle attacks.', 'MEDIUM', 4.8, '3.1', 'Modified', '2021-12-10T19:15:07.827Z', '2026-06-17T03:52:12.040Z'),
  ('CVE-2021-23463', 'The package com.h2database:h2 from 1.4.198 and before 2.0.202 are vulnerable to XML External Entity (XXE) Injection via the org.h2.jdbc.JdbcSQLXML class object, when it receives parsed string data from org.h2.jdbc.JdbcResultSet.getSQLXML() method. If it executes the getSource() method when the parameter is DOMSource.class it will trigger the vulnerability.', 'CRITICAL', 9.1, '3.1', 'Modified', '2021-12-10T20:15:07.917Z', '2026-06-17T03:38:47.610Z'),
  ('CVE-2021-23561', 'All versions of package comb are vulnerable to Prototype Pollution via the deepMerge() function.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T20:15:08.303Z', '2026-06-17T03:38:49.580Z'),
  ('CVE-2021-23639', 'The package md-to-pdf before 5.0.0 are vulnerable to Remote Code Execution (RCE) due to utilizing the library gray-matter to parse front matter content, without disabling the JS engine.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T20:15:08.387Z', '2026-06-17T03:38:50.977Z'),
  ('CVE-2021-23663', 'All versions of package sey are vulnerable to Prototype Pollution via the deepmerge() function.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T20:15:08.453Z', '2026-06-17T03:38:51.350Z'),
  ('CVE-2021-23700', 'All versions of package merge-deep2 are vulnerable to Prototype Pollution via the mergeDeep() function.', 'CRITICAL', 9.8, '3.1', 'Modified', '2021-12-10T20:15:08.527Z', '2026-06-17T03:38:51.803Z'),
  ('CVE-2021-4089', 'snipe-it is vulnerable to Improper Access Control', 'MEDIUM', 4.3, '3.1', 'Modified', '2021-12-10T20:15:08.737Z', '2026-06-17T04:19:00.987Z'),
  ('CVE-2021-43815', 'Grafana is an open-source platform for monitoring and observability. Grafana prior to versions 8.3.2 and 7.5.12 has a directory traversal for arbitrary .csv files. It only affects instances that have the developer testing tool called TestData DB data source enabled and configured. The vulnerability is limited in scope, and only allows access to files with the extension .csv to authenticated users only. Grafana Cloud instances have not been affected by the vulnerability. Versions 8.3.2 and 7.5.12 contain a patch for this issue. There is a workaround available for users who cannot upgrade. Running a reverse proxy in front of Grafana that normalizes the PATH of the request will mitigate the vulnerability. The proxy will have to also be able to handle url encoded paths.', 'MEDIUM', 4.3, '3.1', 'Modified', '2021-12-10T21:15:09.497Z', '2026-06-17T04:11:29.713Z'),
  ('CVE-2020-12890', 'Improper handling of pointers in the System Management Mode (SMM) handling code may allow for a privileged attacker with physical or administrative access to potentially manipulate the AMD Generic Encapsulated Software Architecture (AGESA) to execute arbitrary code undetected by the operating system.', 'MEDIUM', 6.7, '3.1', 'Modified', '2021-12-10T22:15:07.833Z', '2026-06-17T02:52:29.837Z'),
  ('CVE-2021-26340', 'A malicious hypervisor in conjunction with an unprivileged attacker process inside an SEV/SEV-ES guest VM may fail to flush the Translation Lookaside Buffer (TLB) resulting in unexpected behavior inside the virtual machine (VM).', 'HIGH', 8.4, '3.1', 'Modified', '2021-12-10T22:15:08.323Z', '2026-06-17T03:43:10.617Z'),
  ('CVE-2021-41242', 'OpenOlat is a web-basedlearning management system. A path traversal vulnerability exists in OpenOlat prior to versions 15.5.12 and 16.0.5. By providing a filename that contains a relative path as a parameter in some REST methods, it is possible to create directory structures and write files anywhere on the target system. The attack could be used to write files anywhere in the web root folder or outside, depending on the configuration of the system and the properly configured permission of the application server user. The attack requires an OpenOlat user account, an enabled REST API and the rights on a business object to call the vulnerable REST calls. The problem is fixed in version 15.5.12 and 16.0.5. There is a workaround available. The vulnerability requires the REST module to be enabled. Disabling the REST module or limiting the REST module via some firewall or web-server access rules to be accessed only be trusted systems will mitigate the risk.', 'HIGH', 8.1, '3.1', 'Modified', '2021-12-10T23:15:09.527Z', '2026-06-17T04:08:09.473Z')
